-- OWNER APPROVAL REQUIRED. psql -X -v ON_ERROR_STOP=1 -f <this-file>
begin;
set local lock_timeout='5s';
select pg_advisory_xact_lock(20261111,3);
lock table public.answer_key_versions,public.exam_questions,public.grade_cutoff_references in share row exclusive mode;
\ir payload.sql
\ir check_staged.sql
insert into public.answer_key_versions(id,content_item_id,exam_subject_id,paper_variant,version,status,is_current,question_count,max_score,source_name,source_url,source_digest,points_source_name,points_source_url,points_source_digest,fetched_at,verified_at,corrected_at,correction_note,scoring_version,verification_status) select s.id,s.content_item_id,s.exam_subject_id,s.paper_variant,s.version,s.status,s.is_current,s.question_count,s.max_score,s.source_name,s.source_url,s.source_digest,s.points_source_name,s.points_source_url,s.points_source_digest,s.fetched_at,s.verified_at,s.corrected_at,s.correction_note,s.scoring_version,s.verification_status from task03b_keys s where not exists(select 1 from public.answer_key_versions r where r.id=s.id);
insert into public.exam_questions(answer_key_version_id,question_number,answer_type,correct_answer,points,accepted_answers,all_credit,question_id,unit,domain,item_type) select s.answer_key_version_id,s.question_number,s.answer_type,s.correct_answer,s.points,s.accepted_answers,s.all_credit,s.question_id,s.unit,s.domain,s.item_type from task03b_questions s where not exists(select 1 from public.exam_questions r where r.answer_key_version_id=s.answer_key_version_id and r.question_number=s.question_number);
insert into public.grade_cutoff_references(id,content_item_id,exam_subject_id,elective_key,elective_label,grade,revision,is_current,status,raw_score,raw_score_min,raw_score_max,standard_score,percentile,assessment_method,raw_certainty,standard_certainty,source_url,raw_source_url,standard_source_url,source_digest,source_name,fetched_at,verified_at,correction_note) select s.id,s.content_item_id,s.exam_subject_id,s.elective_key,s.elective_label,s.grade,s.revision,s.is_current,s.status,s.raw_score,s.raw_score_min,s.raw_score_max,s.standard_score,s.percentile,s.assessment_method,s.raw_certainty,s.standard_certainty,s.source_url,s.raw_source_url,s.standard_source_url,s.source_digest,s.source_name,s.fetched_at,s.verified_at,s.correction_note from task03b_refs s where not exists(select 1 from public.grade_cutoff_references r where r.id=s.id);
commit;
